import type { Direction } from "../types";

export type AreaRect = { name: string; x: number; y: number; w: number; h: number };

/** Shape of src/game/maps/walkable.json (generated by scripts/build-ship-assets.ts). */
export type WalkableMap = {
  mapId: string;
  mapVersion: number;
  width: number;
  height: number;
  tileSize: number;
  spawn: { x: number; y: number; direction: Direction };
  /** Tile units, in priority order. */
  areas: AreaRect[];
  /** One string per row; "1" = walkable, "0" = blocked. */
  rows: string[];
};

export type TilePoint = { tx: number; ty: number };

/**
 * The character's collision box is its feet: 10 px wide, 6 px tall, with the
 * position being the bottom-centre. Shared by the Phaser body, position
 * validation and (Milestone 2) the server.
 */
export const FOOT_BOX = { width: 10, height: 6 } as const;

export function isWalkableTile(map: WalkableMap, tx: number, ty: number): boolean {
  if (!Number.isInteger(tx) || !Number.isInteger(ty)) return false;
  if (tx < 0 || ty < 0 || tx >= map.width || ty >= map.height) return false;
  return map.rows[ty][tx] === "1";
}

export function tileOf(map: WalkableMap, px: number, py: number): TilePoint {
  return { tx: Math.floor(px / map.tileSize), ty: Math.floor(py / map.tileSize) };
}

export function isWalkablePoint(map: WalkableMap, px: number, py: number): boolean {
  if (!Number.isFinite(px) || !Number.isFinite(py)) return false;
  const { tx, ty } = tileOf(map, px, py);
  return isWalkableTile(map, tx, ty);
}

/** True when the whole foot box of a character standing at (x, y) is on walkable tiles. */
export function isFootprintWalkable(map: WalkableMap, x: number, y: number): boolean {
  if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
  const left = x - FOOT_BOX.width / 2;
  const right = x + FOOT_BOX.width / 2 - 0.001;
  const top = y - FOOT_BOX.height;
  const bottom = y - 0.001;
  return (
    isWalkablePoint(map, left, top) &&
    isWalkablePoint(map, right, top) &&
    isWalkablePoint(map, left, bottom) &&
    isWalkablePoint(map, right, bottom)
  );
}

/** Name of the area containing a pixel position, or null outside all areas. */
export function areaAt(map: WalkableMap, px: number, py: number): string | null {
  const { tx, ty } = tileOf(map, px, py);
  const area = map.areas.find((a) => tx >= a.x && tx < a.x + a.w && ty >= a.y && ty < a.y + a.h);
  return area?.name ?? null;
}

export function walkableTiles(map: WalkableMap): TilePoint[] {
  const out: TilePoint[] = [];
  for (let ty = 0; ty < map.height; ty++)
    for (let tx = 0; tx < map.width; tx++) if (isWalkableTile(map, tx, ty)) out.push({ tx, ty });
  return out;
}

const NEIGHBOURS: ReadonlyArray<readonly [number, number]> = [
  [1, 0],
  [-1, 0],
  [0, 1],
  [0, -1],
];

/** All walkable tiles reachable from `start` (4-connected), as `ty * width + tx` keys. */
export function reachableFrom(map: WalkableMap, start: TilePoint): Set<number> {
  const seen = new Set<number>();
  if (!isWalkableTile(map, start.tx, start.ty)) return seen;
  const queue: TilePoint[] = [start];
  seen.add(start.ty * map.width + start.tx);
  while (queue.length) {
    const { tx, ty } = queue.shift()!;
    for (const [dx, dy] of NEIGHBOURS) {
      const nx = tx + dx;
      const ny = ty + dy;
      const key = ny * map.width + nx;
      if (!seen.has(key) && isWalkableTile(map, nx, ny)) {
        seen.add(key);
        queue.push({ tx: nx, ty: ny });
      }
    }
  }
  return seen;
}

/** Shortest 4-connected path over walkable tiles, including both ends; null if unreachable. */
export function findPath(map: WalkableMap, from: TilePoint, to: TilePoint, maxNodes = 4000): TilePoint[] | null {
  if (!isWalkableTile(map, from.tx, from.ty) || !isWalkableTile(map, to.tx, to.ty)) return null;
  const startKey = from.ty * map.width + from.tx;
  const goalKey = to.ty * map.width + to.tx;
  const prev = new Map<number, number>([[startKey, -1]]);
  const queue = [startKey];
  for (let head = 0; head < queue.length && head < maxNodes; head++) {
    const key = queue[head];
    if (key === goalKey) break;
    const tx = key % map.width;
    const ty = Math.floor(key / map.width);
    for (const [dx, dy] of NEIGHBOURS) {
      const nx = tx + dx;
      const ny = ty + dy;
      const nKey = ny * map.width + nx;
      if (!prev.has(nKey) && isWalkableTile(map, nx, ny)) {
        prev.set(nKey, key);
        queue.push(nKey);
      }
    }
  }
  if (!prev.has(goalKey)) return null;
  const path: TilePoint[] = [];
  for (let k = goalKey; k !== -1; k = prev.get(k)!) path.push({ tx: k % map.width, ty: Math.floor(k / map.width) });
  return path.reverse();
}
